<?php
declare(strict_types=1);
/** Append-only account-scoped task snapshots, separate from mutable planner/Undo state. */
final class LifeTaskHistory {
    public function __construct(private LifeStore $store) {$store->db->exec('CREATE TABLE IF NOT EXISTS life_task_history (id VARCHAR(32) PRIMARY KEY, tenant_id INT NOT NULL, event_key VARCHAR(100) NOT NULL, status VARCHAR(20) NOT NULL, recorded_at VARCHAR(30) NOT NULL, snapshot LONGTEXT NOT NULL, UNIQUE (tenant_id,event_key))');}
    private static function statuses(array $task,array $state):array {$list=null;foreach($state['lists']??[] as $row)if($row['id']===$task['listId'])$list=$row;$out=[];if(($list['isDone']??false)||!empty($task['completedAt']))$out[]='done';if(mb_strtolower(trim($list['name']??''))==='blocked'||trim($task['blocker']??'')!=='')$out[]='blocked';if($task['archived']??false)$out[]='archived';return $out;}
    private function append(array $task,array $state,string $status,string $key,string $action):void {$list=[];$board=[];foreach($state['lists']??[] as $row)if($row['id']===$task['listId'])$list=$row;foreach($state['boards']??[$state['board']] as $row)if($row['id']===($list['boardId']??$state['board']['id']))$board=$row;$snapshot=['task'=>$task,'boardName'=>$board['name']??$state['board']['name'],'listName'=>$list['name']??'','action'=>$action];$sql=$this->store->db->getAttribute(PDO::ATTR_DRIVER_NAME)==='sqlite'?'INSERT OR IGNORE':'INSERT IGNORE';$this->store->db->prepare($sql.' INTO life_task_history (id,tenant_id,event_key,status,recorded_at,snapshot) VALUES (?,?,?,?,?,?)')->execute([LifeStore::id(),$this->store->tenantId,$key,$status,LifeStore::now(),json_encode($snapshot,JSON_THROW_ON_ERROR)]);}
    public function seed(array $state):void {$q=$this->store->db->prepare('SELECT id FROM life_task_history WHERE tenant_id=? LIMIT 1');$q->execute([$this->store->tenantId]);if($q->fetchColumn())return;foreach($state['tasks']??[] as $task)foreach(self::statuses($task,$state) as $status)$this->append($task,$state,$status,'existing-'.$task['id'].'-'.$status,'existing');}
    public function capture(array $before,array $after,string $action,int $version):void {$this->seed($before);$old=[];foreach($before['tasks']??[] as $task)$old[$task['id']]=$task;foreach($after['tasks']??[] as $task){$prior=isset($old[$task['id']])?self::statuses($old[$task['id']],$before):[];foreach(array_diff(self::statuses($task,$after),$prior) as $status)$this->append($task,$after,$status,$version.'-'.$task['id'].'-'.$status,$action);}}
    public function export():array {$this->seed($this->store->read()['state']);$q=$this->store->db->prepare('SELECT id,status,recorded_at,snapshot FROM life_task_history WHERE tenant_id=? ORDER BY recorded_at,id');$q->execute([$this->store->tenantId]);return $q->fetchAll(PDO::FETCH_ASSOC);}
    public function page(array $args=[]):array {$this->seed($this->store->read()['state']);$status=LifeStore::text($args['status']??'',20);if(!in_array($status,['','done','blocked','archived'],true))throw new LifeError('Choose a valid history status.');$offset=max(0,min(1000000,(int)($args['offset']??0)));$q=$this->store->db->prepare('SELECT id,status,recorded_at,snapshot FROM life_task_history WHERE tenant_id=?'.($status!==''?' AND status=?':'').' ORDER BY recorded_at DESC,id DESC LIMIT 101 OFFSET '.$offset);$q->execute($status!==''?[$this->store->tenantId,$status]:[$this->store->tenantId]);$rows=$q->fetchAll(PDO::FETCH_ASSOC);$more=count($rows)>100;$entries=[];foreach(array_slice($rows,0,100) as $row)$entries[]=['id'=>$row['id'],'status'=>$row['status'],'recordedAt'=>$row['recorded_at']]+json_decode($row['snapshot'],true,512,JSON_THROW_ON_ERROR);return ['entries'=>$entries,'nextOffset'=>$more?$offset+100:null];}
}
